#### Example 1: k6 Load Test for Member Portal Login API

```javascript
// k6/member-portal-login-test.js
import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Rate, Trend } from 'k6/metrics';

// Custom metrics
const loginFailureRate = new Rate('login_failures');
const loginDuration = new Trend('login_duration');

// Test configuration
export let options = {
  stages: [
    { duration: '2m', target: 100 },    // Ramp up to 100 users
    { duration: '5m', target: 500 },    // Ramp up to 500 users
    { duration: '10m', target: 1000 },  // Ramp up to 1000 users
    { duration: '15m', target: 1000 },  // Hold at 1000 users (peak load)
    { duration: '5m', target: 2500 },   // Spike to 2500 users
    { duration: '5m', target: 1000 },   // Return to 1000 users
    { duration: '5m', target: 0 },      // Ramp down
  ],

  thresholds: {
    'http_req_duration': [
      'p(95)<2000',   // 95% of requests under 2s
      'p(99)<3000',   // 99% of requests under 3s
    ],
    'http_req_failed': ['rate<0.01'],  // Error rate under 1%
    'login_failures': ['rate<0.01'],
    'login_duration': ['p(95)<1000'],  // Login-specific: 95% under 1s
  },
};

const BASE_URL = __ENV.API_URL || 'https://memberportal.gainwell.com';

// Test data: realistic member credentials
const members = Array.from({ length: 10000 }, (_, i) => ({
  username: `member${1000000 + i}@gainwell.com`,
  password: 'TestPassword123!',
  memberId: 1000000 + i
}));

export default function() {
  // Each virtual user gets a unique member
  const member = members[__VU % members.length];

  group('Member Login Flow', function() {
    // Step 1: Login
    const loginPayload = JSON.stringify({
      username: member.username,
      password: member.password
    });

    const loginRes = http.post(`${BASE_URL}/api/auth/login`, loginPayload, {
      headers: { 'Content-Type': 'application/json' },
      tags: { name: 'MemberLogin' },
    });

    const loginSuccess = check(loginRes, {
      'login status 200': (r) => r.status === 200,
      'login has token': (r) => r.json('accessToken') !== undefined,
      'login response time OK': (r) => r.timings.duration < 1000,
    });

    loginFailureRate.add(!loginSuccess);
    loginDuration.add(loginRes.timings.duration);

    if (!loginSuccess) {
      console.error(`Login failed for ${member.username}: ${loginRes.status}`);
      return;
    }

    const token = loginRes.json('accessToken');
    sleep(Math.random() * 3 + 2);  // Think time: 2-5 seconds

    // Step 2: Fetch member profile
    const profileRes = http.get(`${BASE_URL}/api/member/profile`, {
      headers: { 'Authorization': `Bearer ${token}` },
      tags: { name: 'GetProfile' },
    });

    check(profileRes, {
      'profile status 200': (r) => r.status === 200,
      'profile has data': (r) => r.json('memberId') === member.memberId,
    });

    sleep(Math.random() * 5 + 3);  // Think time: 3-8 seconds
  });
}

// Custom summary handler
export function handleSummary(data) {
  return {
    'stdout': textSummary(data, { indent: ' ', enableColors: true }),
    'summary.json': JSON.stringify(data),
    'summary.html': htmlReport(data),
  };
}
```

